-- ---------------------------------------------------------------------------
-- 0. Prerequisites: fail loudly instead of half-applying.
-- ---------------------------------------------------------------------------
DO $$
DECLARE
  missing text[] := ARRAY[]::text[];
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['auth.users', 'public.profiles', 'public.user_roles'] LOOP
    IF to_regclass(t) IS NULL THEN missing := missing || t; END IF;
  END LOOP;
  IF to_regprocedure('auth.uid()') IS NULL THEN missing := missing || 'function auth.uid()'::text; END IF;
  IF to_regprocedure('auth.jwt()') IS NULL THEN missing := missing || 'function auth.jwt()'::text; END IF;
  IF array_length(missing, 1) IS NOT NULL THEN
    RAISE EXCEPTION 'mfa_backup_codes_and_aal2: missing prerequisites: %', array_to_string(missing, ', ');
  END IF;
END
$$;

-- =============================================================================
-- A. Backup codes
-- =============================================================================
CREATE TABLE IF NOT EXISTS public.mfa_backup_codes (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id      uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  batch_id     uuid NOT NULL,
  code_hash    text NOT NULL,
  salt         text NOT NULL,
  pepper_id    text NOT NULL,
  hash_version text NOT NULL DEFAULT 'v1',
  created_at   timestamptz NOT NULL DEFAULT now(),
  used_at      timestamptz
);

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint
                 WHERE conrelid = 'public.mfa_backup_codes'::regclass
                   AND conname = 'mfa_backup_codes_code_hash_format') THEN
    ALTER TABLE public.mfa_backup_codes
      ADD CONSTRAINT mfa_backup_codes_code_hash_format CHECK (code_hash ~ '^[0-9a-f]{64}$');
  END IF;
END
$$;

CREATE UNIQUE INDEX IF NOT EXISTS mfa_backup_codes_user_hash_key
  ON public.mfa_backup_codes (user_id, code_hash);
CREATE INDEX IF NOT EXISTS mfa_backup_codes_user_unused_idx
  ON public.mfa_backup_codes (user_id) WHERE used_at IS NULL;

COMMENT ON TABLE public.mfa_backup_codes IS
  'S0-10: MFA backup codes. code_hash = hex HMAC-SHA-256(pepper[pepper_id], v1|user_id|salt|CODE); the pepper is an edge-function secret. Service role only.';

CREATE TABLE IF NOT EXISTS public.mfa_backup_code_attempts (
  id           bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  user_id      uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  succeeded    boolean NOT NULL,
  attempted_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE INDEX IF NOT EXISTS mfa_backup_code_attempts_user_time_idx
  ON public.mfa_backup_code_attempts (user_id, attempted_at DESC);

COMMENT ON TABLE public.mfa_backup_code_attempts IS
  'S0-10: backup-code attempts for the recovery lockout (5 failures / 15 min). Service role only.';

-- RLS on with no policies: anon/authenticated see nothing even if a grant slips back.
ALTER TABLE public.mfa_backup_codes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.mfa_backup_code_attempts ENABLE ROW LEVEL SECURITY;
-- Supabase's default privileges grant ALL on new public tables to anon and
-- authenticated; take them back explicitly.
REVOKE ALL ON public.mfa_backup_codes FROM PUBLIC, anon, authenticated;
REVOKE ALL ON public.mfa_backup_code_attempts FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.mfa_backup_codes TO service_role;
GRANT SELECT, INSERT, DELETE ON public.mfa_backup_code_attempts TO service_role;

-- Atomic, single-use consumption with a lockout. Called only by verify-backup-code
-- (service role) with the candidate hashes it computed for the submitted code.
-- Returns {"status":"ok","code_id":...,"remaining":n} | {"status":"invalid"} |
--         {"status":"locked","retry_after_seconds":n}.
CREATE OR REPLACE FUNCTION public.consume_mfa_backup_code(p_user_id uuid, p_code_hashes text[])
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  c_window      constant interval := interval '15 minutes';
  c_max_fail    constant int := 5;
  v_last_ok     timestamptz;
  v_failures    int;
  v_oldest_fail timestamptz;
  v_id          uuid;
  v_remaining   int;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'consume_mfa_backup_code: user id is required' USING ERRCODE = '22004';
  END IF;

  -- Serialise attempts per user so the lockout count cannot be raced.
  PERFORM pg_advisory_xact_lock(hashtextextended('mfa_backup_code:' || p_user_id::text, 0));

  -- Housekeeping: attempt rows older than a day no longer matter.
  DELETE FROM public.mfa_backup_code_attempts
   WHERE user_id = p_user_id AND attempted_at < clock_timestamp() - interval '1 day';

  SELECT max(attempted_at) INTO v_last_ok
    FROM public.mfa_backup_code_attempts
   WHERE user_id = p_user_id AND succeeded;

  SELECT count(*), min(attempted_at) INTO v_failures, v_oldest_fail
    FROM public.mfa_backup_code_attempts
   WHERE user_id = p_user_id
     AND NOT succeeded
     AND attempted_at > clock_timestamp() - c_window
     AND attempted_at > coalesce(v_last_ok, '-infinity'::timestamptz);

  IF v_failures >= c_max_fail THEN
    RETURN jsonb_build_object(
      'status', 'locked',
      'retry_after_seconds', greatest(1, ceil(extract(epoch FROM (v_oldest_fail + c_window - clock_timestamp())))::int)
    );
  END IF;

  -- Single statement; the outer "used_at IS NULL" is re-checked after any row
  -- lock wait, so two concurrent callers can never both consume the same row.
  UPDATE public.mfa_backup_codes AS c
     SET used_at = clock_timestamp()
   WHERE c.id = (
           SELECT id FROM public.mfa_backup_codes
            WHERE user_id = p_user_id
              AND used_at IS NULL
              AND code_hash = ANY (coalesce(p_code_hashes, ARRAY[]::text[]))
            ORDER BY created_at
            LIMIT 1)
     AND c.used_at IS NULL
  RETURNING c.id INTO v_id;

  INSERT INTO public.mfa_backup_code_attempts (user_id, succeeded, attempted_at)
  VALUES (p_user_id, v_id IS NOT NULL, clock_timestamp());

  IF v_id IS NULL THEN
    RETURN jsonb_build_object('status', 'invalid');
  END IF;

  SELECT count(*) INTO v_remaining
    FROM public.mfa_backup_codes WHERE user_id = p_user_id AND used_at IS NULL;
  RETURN jsonb_build_object('status', 'ok', 'code_id', v_id, 'remaining', v_remaining);
END;
$$;

-- Replace the user's unused codes with a new batch, in one transaction.
-- Called only by generate-backup-codes (service role) after it checked aal2.
CREATE OR REPLACE FUNCTION public.replace_mfa_backup_codes(
  p_user_id uuid, p_salt text, p_pepper_id text, p_code_hashes text[])
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_batch uuid := gen_random_uuid();
  v_count int;
BEGIN
  IF p_user_id IS NULL OR coalesce(p_salt, '') = '' OR coalesce(p_pepper_id, '') = '' THEN
    RAISE EXCEPTION 'replace_mfa_backup_codes: user id, salt and pepper id are required' USING ERRCODE = '22004';
  END IF;
  IF coalesce(array_length(p_code_hashes, 1), 0) NOT BETWEEN 5 AND 20 THEN
    RAISE EXCEPTION 'replace_mfa_backup_codes: expected 5..20 hashes' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (SELECT 1 FROM unnest(p_code_hashes) h WHERE h IS NULL OR h !~ '^[0-9a-f]{64}$') THEN
    RAISE EXCEPTION 'replace_mfa_backup_codes: hashes must be 64 lower-case hex characters' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('mfa_backup_code:' || p_user_id::text, 0));

  -- Unused codes from earlier batches stop working; used rows stay as history.
  DELETE FROM public.mfa_backup_codes WHERE user_id = p_user_id AND used_at IS NULL;

  INSERT INTO public.mfa_backup_codes (user_id, batch_id, code_hash, salt, pepper_id)
  SELECT p_user_id, v_batch, h, p_salt, p_pepper_id
    FROM (SELECT DISTINCT h FROM unnest(p_code_hashes) AS h) d;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;

-- How many unused codes the caller has left (no hashes exposed). For the UI.
CREATE OR REPLACE FUNCTION public.my_mfa_backup_codes_remaining()
RETURNS integer
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT count(*)::int FROM public.mfa_backup_codes
   WHERE user_id = auth.uid() AND used_at IS NULL
$$;

REVOKE ALL ON FUNCTION public.consume_mfa_backup_code(uuid, text[]) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.replace_mfa_backup_codes(uuid, text, text, text[]) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.my_mfa_backup_codes_remaining() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.consume_mfa_backup_code(uuid, text[]) TO service_role;
GRANT EXECUTE ON FUNCTION public.replace_mfa_backup_codes(uuid, text, text, text[]) TO service_role;
GRANT EXECUTE ON FUNCTION public.my_mfa_backup_codes_remaining() TO authenticated, service_role;

-- =============================================================================
-- B. Profiles: privileged columns are server-managed (SECF-02, EDGE-05)
-- =============================================================================
-- The profiles UPDATE policy is "user_id = auth.uid()" with no column limit, so
-- a user could PATCH two_factor_enabled, hospital_id, is_active or is_staff on
-- their own row. A trigger (rather than column GRANTs) is used because it
-- tolerates columns that may or may not exist live (checked through to_jsonb)
-- and does not break clients that send unchanged values.
--
-- Restricted callers: current_user anon or authenticated (PostgREST requests).
-- Allowed: service_role (edge functions), postgres, supabase_auth_admin, and
-- SECURITY DEFINER functions (they run as their owner), e.g. the
-- recompute_two_factor_required trigger and create-hospital-admin.
-- Allowed even for end users (they only reduce privilege): is_staff -> false,
-- two_factor_enabled -> false, two_factor_secret -> NULL.
--
-- Known client impact (S0-03 must move these to server code):
--   src/pages/patient/PatientRegisterPage.tsx sets hospital_id on self-registration,
--   src/components/admin/AdminRepairTool.tsx sets hospital_id. Both now get 42501.
CREATE OR REPLACE FUNCTION public.profiles_guard_privileged_columns()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
DECLARE
  v_new jsonb := to_jsonb(NEW);
  v_old jsonb;
  c     text;
  v_protected constant text[] := ARRAY[
    'id', 'user_id', 'hospital_id', 'is_active', 'is_staff', 'role',
    'two_factor_enabled', 'two_factor_required', 'two_factor_secret',
    'failed_login_attempts', 'locked_until'];
BEGIN
  IF current_user NOT IN ('anon', 'authenticated') THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF (v_new ->> 'hospital_id') IS NOT NULL
       OR coalesce((v_new ->> 'is_staff')::boolean, false)
       OR coalesce((v_new ->> 'two_factor_enabled')::boolean, false)
       OR coalesce((v_new ->> 'two_factor_required')::boolean, false)
       OR (v_new ->> 'two_factor_secret') IS NOT NULL
       OR (v_new ->> 'locked_until') IS NOT NULL
       OR coalesce((v_new ->> 'failed_login_attempts')::int, 0) <> 0 THEN
      RAISE EXCEPTION 'profiles: hospital_id, is_staff, two_factor_* and lockout columns are set by the server'
        USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
  END IF;

  v_old := to_jsonb(OLD);
  FOREACH c IN ARRAY v_protected LOOP
    IF (v_new -> c) IS DISTINCT FROM (v_old -> c) THEN
      IF c = 'is_staff' AND (v_new -> c) = 'false'::jsonb THEN CONTINUE; END IF;
      IF c = 'two_factor_enabled' AND (v_new -> c) = 'false'::jsonb THEN CONTINUE; END IF;
      IF c = 'two_factor_secret' AND (v_new -> c) = 'null'::jsonb THEN CONTINUE; END IF;
      RAISE EXCEPTION 'profiles.% is managed by the server and cannot be changed by the user', c
        USING ERRCODE = '42501';
    END IF;
  END LOOP;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS profiles_guard_privileged_columns ON public.profiles;
CREATE TRIGGER profiles_guard_privileged_columns
  BEFORE INSERT OR UPDATE ON public.profiles
  FOR EACH ROW EXECUTE FUNCTION public.profiles_guard_privileged_columns();

-- =============================================================================
-- C. public.mfa_satisfied()
-- =============================================================================
-- Same role list as 20260622000001_enforce_2fa_for_clinical_roles.sql. Created
-- here only if that migration never ran live (an existing definition is kept).
DO $$
BEGIN
  IF to_regprocedure('public.role_requires_2fa(text)') IS NULL THEN
    EXECUTE $f$
      CREATE FUNCTION public.role_requires_2fa(p_role text)
      RETURNS boolean
      LANGUAGE sql IMMUTABLE
      AS $b$ SELECT p_role IN ('admin', 'doctor') $b$
    $f$;
  END IF;
END
$$;

-- True when the caller's session is aal2 (Supabase Auth MFA verified), or when
-- none of the caller's roles requires 2FA. False for a caller with no auth.uid().
-- SECURITY DEFINER so it can read user_roles regardless of that table's RLS (and
-- without policy recursion). Use it in policies as (SELECT public.mfa_satisfied())
-- so it is evaluated once per statement.
CREATE OR REPLACE FUNCTION public.mfa_satisfied()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT CASE
    WHEN auth.uid() IS NULL THEN false
    WHEN coalesce(auth.jwt() ->> 'aal', '') = 'aal2' THEN true
    ELSE NOT EXISTS (
      SELECT 1 FROM public.user_roles ur
       WHERE ur.user_id = auth.uid()
         AND public.role_requires_2fa(ur.role::text))
  END
$$;

REVOKE ALL ON FUNCTION public.mfa_satisfied() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.mfa_satisfied() TO authenticated, service_role;

COMMENT ON FUNCTION public.mfa_satisfied() IS
  'S0-10: true if auth.jwt()->>''aal'' = ''aal2'' or the caller holds no role for which role_requires_2fa() is true.';

-- =============================================================================
-- D. PHI tables: require mfa_satisfied()
-- =============================================================================
-- *****************************************************************************
-- ** OPERATOR: RECONCILE THIS BLOCK AGAINST THE S0-01 LIVE-SCHEMA CAPTURE.  **
-- *****************************************************************************
-- The live policies on these tables are not known until S0-01 is done, so this
-- block does NOT rewrite them. It adds one RESTRICTIVE policy per table.
-- PostgreSQL combines restrictive policies with AND against the OR of the
-- permissive ones, so the effect is exactly "every existing policy
-- AND public.mfa_satisfied()", whatever the existing policies are, and the
-- block stays correct when S0-04 later rewrites them.
--
-- Before promoting, check in the capture (live_rls_summary.tsv, live_public_schema.sql):
--   1. The table list. Add other PHI tables that admin/doctor read (candidates:
--      documents, patient_consents, medication_administrations,
--      telemedicine_sessions, shift_handovers, appointments, insurance_claims,
--      invoices, lab_results if it exists). Remove nothing without a reason.
--   2. RLS is enabled on each table. A restrictive policy does nothing on a table
--      with RLS off (DB-13); this block warns but does not enable RLS, because
--      enabling RLS without permissive policies would hide every row.
--   3. Edge functions that read these tables with a USER-JWT client (not the
--      service role) now need an aal2 token for admin/doctor callers.
--   4. Whether writes should also require aal2 (this block uses FOR ALL, so
--      INSERT/UPDATE/DELETE are covered too). Narrow it to FOR SELECT only if a
--      reviewed aal1 write path for admin/doctor must keep working.
-- Rollout: every admin and doctor must enroll a Supabase MFA factor first. Until
-- they do, they cannot reach aal2 and see 0 rows in these tables.
DO $$
DECLARE
  t text;
  v_rls boolean;
  v_tables constant text[] := ARRAY[
    'patients', 'consultations', 'prescriptions', 'prescription_items',
    'lab_orders', 'vital_signs', 'medical_records'];
BEGIN
  FOREACH t IN ARRAY v_tables LOOP
    IF to_regclass(format('public.%I', t)) IS NULL THEN
      RAISE WARNING 'mfa_aal2_required: table public.% does not exist; skipped', t;
      CONTINUE;
    END IF;
    SELECT relrowsecurity INTO v_rls FROM pg_class WHERE oid = to_regclass(format('public.%I', t));
    IF NOT v_rls THEN
      RAISE WARNING 'mfa_aal2_required: RLS is DISABLED on public.%; the policy has no effect until RLS is enabled (S0-04)', t;
    END IF;
    EXECUTE format('DROP POLICY IF EXISTS mfa_aal2_required ON public.%I', t);
    EXECUTE format(
      'CREATE POLICY mfa_aal2_required ON public.%I AS RESTRICTIVE FOR ALL TO authenticated '
      'USING ((SELECT public.mfa_satisfied())) WITH CHECK ((SELECT public.mfa_satisfied()))', t);
  END LOOP;
END
$$;

COMMIT;
